# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">UYARILARIN YORUMLANMASI VE REFLEKS YAYI MEKANİZMASI</text>\n  <rect x="30" y="50" width="305" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Refleks Yayının Sıralı Basamakları</text>\n  <text x="45" y="102" font-size="11" fill="#334155">1. Reseptör (Duyu almaçları uyarıyı alır)</text>\n  <text x="45" y="124" font-size="11" fill="#334155">2. Duyu Nöronu (Arka kökten omuriliğe girer)</text>\n  <text x="45" y="146" font-size="11" fill="#334155">3. Ara Nöron (Omurilik boz maddesinde değerlendirir)</text>\n  <text x="45" y="168" font-size="11" fill="#334155">4. Motor Nöron (Ön kökten omurilikten çıkar)</text>\n  <text x="45" y="190" font-size="11" fill="#334155">5. Efektör Organ (Kas veya salgı bezi tepki verir)</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Diz kapağı refleksinde ara nöron bulunmaz (2 nöronlu)!</text>\n  <rect x="365" y="50" width="305" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Kalıtsal ve Kazanılmış Refleksler</text>\n  <text x="380" y="105" font-size="11.5" font-weight="bold" fill="#166534">Doğuştan (Kalıtsal) Refleksler:</text>\n  <text x="380" y="125" font-size="11" fill="#334155">• Göz bebeği, emme, diz kapağı, el çekme</text>\n  <text x="380" y="155" font-size="11.5" font-weight="bold" fill="#15803d">Sonradan Kazanılan Refleksler:</text>\n  <text x="380" y="175" font-size="11" fill="#334155">• Önce uç beyin öğrenir, sonra omurilik devralır</text>\n  <text x="380" y="195" font-size="11" fill="#475569">(Bisiklet sürme, yüzme, örgü örme, limon görünce</text>\n  <text x="380" y="213" font-size="11" fill="#475569">ağzın sulanması). Hata olunca uç beyin müdahale eder.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">OMURGASIZ HAYVANLARDA SİNİR SİSTEMİ ORGANİZASYONU</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="127" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Süngerler (Sinir Yok)</text>\n  <text x="40" y="105" font-size="11" fill="#334155">• Özelleşmiş sinir hücresi</text>\n  <text x="50" y="123" font-size="11" fill="#475569">(nöron) ve sinir sistemi</text>\n  <text x="50" y="141" font-size="11" fill="#475569">bulunmayan tek hayvan</text>\n  <text x="50" y="159" font-size="11" fill="#475569">grubudur.</text>\n  <text x="40" y="185" font-size="11" fill="#334155">• Uyarılar hücreden hücreye</text>\n  <text x="50" y="203" font-size="11" fill="#475569">kimyasal yolla iletilir.</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Diffüz (Ağsı) Sinir Sistemi</text>\n  <text x="262" y="105" font-size="11" fill="#334155">• Hidra, deniz anası ve mercan</text>\n  <text x="272" y="123" font-size="11" fill="#475569">(sölenterler/knidliler) grubunda.</text>\n  <text x="262" y="150" font-size="11" fill="#334155">• Merkezî-çevresel ayrımı ve</text>\n  <text x="272" y="168" font-size="11" fill="#475569">beyin yoktur; nöronlar ağ gibi</text>\n  <text x="272" y="186" font-size="11" fill="#475569">tüm vücuda yayılmıştır.</text>\n  <text x="350" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Tüm vücut birlikte tepki verir</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="572" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">İp Merdiven Sinir Sistemi</text>\n  <text x="485" y="105" font-size="11" fill="#334155">• Planarya (yassı solucan),</text>\n  <text x="495" y="123" font-size="11" fill="#475569">toprak solucanı ve eklem</text>\n  <text x="495" y="141" font-size="11" fill="#475569">bacaklılarda (böcekler) görülür.</text>\n  <text x="485" y="166" font-size="11" fill="#334155">• Başta gangliyon (sinir düğümü)</text>\n  <text x="495" y="184" font-size="11" fill="#475569">ve karın bölgesinde boyuna</text>\n  <text x="495" y="202" font-size="11" fill="#475569">uzanan sinir kordonları vardır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">OMURGASIZ VE OMURGALI SİNİR SİSTEMİNİN ANALOJİK KARŞILAŞTIRMASI</text>\n  <rect x="35" y="55" width="300" height="175" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="185" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Omurgasızlar (Merkezîleşmeye Geçiş)</text>\n  <text x="50" y="110" font-size="11.5" fill="#334155">• Süngerlerde sinir hücresi yoktur.</text>\n  <text x="50" y="135" font-size="11.5" fill="#334155">• Hidrada merkezîleşme olmayan ağsı sistem.</text>\n  <text x="50" y="160" font-size="11.5" fill="#334155">• Planarya ve böceklerde ilk merkezîleşme:</text>\n  <text x="62" y="178" font-size="11" fill="#475569">Baş gangliyonları + Karın (ventral) sinir kordonu.</text>\n  <text x="50" y="205" font-size="11.5" fill="#334155">• Ahtapot (yumuşakça): Gelişmiş beyin yapısı.</text>\n  <rect x="365" y="55" width="300" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="515" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Omurgalılar (Gelişmiş Boru Tipi Sistem)</text>\n  <text x="380" y="110" font-size="11.5" fill="#334155">• Balık, kurbağa, sürüngen, kuş ve memeliler.</text>\n  <text x="380" y="135" font-size="11.5" fill="#334155">• Merkezî (beyin ve omurilik) ve çevresel</text>\n  <text x="392" y="153" font-size="11" fill="#475569">sinir sistemi kesin olarak ayrılmıştır.</text>\n  <text x="380" y="180" font-size="11.5" fill="#334155">• Sinir şeridi vücudun sırt (dorsal) kısmında</text>\n  <text x="392" y="198" font-size="11" fill="#475569">içi boş boru şeklinde omurga içinde korunur.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
